```python
tasks = {}

def add_task(task):
    """Add a task to the To-Do list."""
    task_name, _ = task.strip().split()
    tasks[task_name] = "Not completed"

def remove_task(task):
    """Remove a task from the To-Do list."""
    task_name, _ = task.strip().split()
    if task_name in tasks:
        del tasks[task_name]

def mark_task_as_completed(task):
    """Mark a task as completed in the To-Do list."""
    task_name, _ = task.strip().split()
    if task_name in tasks:
        tasks[task_name] = "Completed"

def print_tasks():
    """Print the current To-Do list."""
    for task_name, status in tasks.items():
        print(f"{task_name}: {status}")

while True:
    user_input = input("Enter a command (add, remove, mark, or quit): ").lower()

    if user_input == "add":
        add_task(input("Enter a task: "))

    elif user_input == "remove":
        remove_task(input("Enter a task: "))

    elif user_input == "mark":
        mark_task_as_completed(input("Enter a task: "))

    elif user_input == "quit":
        break

    else:
        print("Invalid command. Please try again.")

print_tasks()
```

This program will continuously prompt the user for commands until they enter "quit". Each command is then executed using the corresponding function, and the updated To-Do list is printed after each command.
